import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";

const DemoModeIndicator = () => {
    const user = useSelector(store => store.user);
    const navigate = useNavigate();
    
    if (!user?.isDemo) {
        return null;
    }

    return (
        <div className="fixed bottom-4 right-4 z-50">
            <div className="bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 p-4 rounded-lg shadow-lg">
                <div className="flex items-center">
                    <div className="flex-shrink-0">
                        <svg className="h-5 w-5 text-yellow-500" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                        </svg>
                    </div>
                    <div className="ml-3">
                        <p className="text-sm font-medium">
                            You're in Demo Mode
                        </p>
                        <p className="text-xs mt-1">
                            Experience our app without an account
                        </p>
                    </div>
                </div>
                
                <div className="mt-3 flex justify-end">
                    <button 
                        onClick={() => navigate('/login')}
                        className="text-xs font-medium text-yellow-800 hover:text-yellow-900 underline"
                    >
                        Sign up for full access
                    </button>
                </div>
            </div>
        </div>
    );
};

export default DemoModeIndicator; 